window.docContents[160].resolve({"/2___-Basic-notions-of-representation-theory/2___7___-Examples-of-algebras/Center___-ideals___-and-representations-of-the-q-Weyl-algebra/#Chapter2___Problem2___7___5":{"contents":"Problem 2.7.5. Let q be a nonzero complex number, and let A be the q-Weyl algebra over \\mathbb{C}.\n\n(a) What is the center of A for different q? If q is not a root of unity, what are the two-sided ideals in A?\n\n(b) For which q does this algebra have finite dimensional representations?\n\nHint: Use determinants.\n\n(c) Find all finite dimensional irreducible representations of A for such q.\n\nHint: This is similar to part (c) of the previous problem.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.7. Examples of algebras\tCenter, ideals, and representations of the q-Weyl algebra","header":"Center, ideals, and representations of the q-Weyl algebra","id":"/2___-Basic-notions-of-representation-theory/2___7___-Examples-of-algebras/Center___-ideals___-and-representations-of-the-q-Weyl-algebra/#Chapter2___Problem2___7___5"},"/5___-Representations-of-finite-groups___-Further-results/5___4___-Burnside___s-theorem/Historical-note-on-Burnside___s-theorem-and-proof-plan/#Chapter5___Discussion_after_Theorem5___4___3":{"contents":"This famous result in group theory was proved by the British mathematician William Burnside in the early 20th century, using representation theory (see Section 5.5 and [Cu]). Here is this proof, presented in modern language.\n\nBefore proving Burnside's theorem, we will prove several other results which are of independent interest.\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.4. Burnside's theorem\tHistorical note on Burnside's theorem and proof plan","header":"Historical note on Burnside's theorem and proof plan","id":"/5___-Representations-of-finite-groups___-Further-results/5___4___-Burnside___s-theorem/Historical-note-on-Burnside___s-theorem-and-proof-plan/#Chapter5___Discussion_after_Theorem5___4___3"}});
